SELECT userId, nickname, realName, email, regdate, status FROM ( SELECT T.*, ROWNUM AS RNUM FROM ( SELECT user_id as userId, nickname, real_name as realName, email, regdate, CASE user_status_id WHEN 1 THEN '활동중' WHEN 2 THEN '정지' ELSE '알 수 없음' END as status FROM tblUser
AND real_name LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%'
AND email LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%'
AND user_status_id = #{status, jdbcType=INTEGER}
ORDER BY regdate DESC ) T WHERE ROWNUM <= #{endRow} ) WHERE RNUM >= #{startRow}

mapper.update:
UPDATE tblUser SET
    user_status_id = #{statusId}
WHERE user_id = #{userId}
